#include "../Core/CoreCoordinator.hpp"
#include <stdexcept>
#include <iostream>
#include <array>
using namespace xone::l01;
static unsigned count=0;
static void require(bool p,const char*m){if(!p)throw std::runtime_error(m);}
static void scenario(const char*n,void(*f)()){f();std::cout<<"PASS "<<n<<'\n';++count;}
static GestureEvent edge(int c,int v){return {GestureEventKind::RawEdge,c,v,-1,{}};}
static GestureEvent qual(int r,QualifiedPhase p){return {GestureEventKind::Qualified,-1,0,r,p};}
static GestureEvent dj(int n,int v){return {GestureEventKind::RawDj,n,v,-1,{}};}
static GestureEvent cc(int n,int v){return {GestureEventKind::RawCc,n,v,-1,{}};}
static S3ProposalBatch feed(S3DecisionBoundary& d,std::initializer_list<GestureEvent> ev){GestureBatch b{};for(auto e:ev)require(b.push(e),"batch");S3ProposalBatch out{};require(d.accept(b,out),"accept");return out;}
static void push(CoreCoordinator& c,int cmd,int n,int v,int t){require(c.onMidi({14,cmd,n,v},t),"pipeline midi");}
static bool contains(const S3ProposalBatch& p,S3ProposalKind k,int role){for(std::size_t i=0;i<p.count;++i)if(p.items[i].kind==k&&p.items[i].role==role)return true;return false;}
int main(){try {
scenario("S3-UNKNOWN-NAV-NO-PHANTOM",[](){S3DecisionBoundary s;feed(s,{edge(1,1)});auto p=feed(s,{qual(1,QualifiedPhase::Short)});require(!p.count&&s.held(1),"unknown nav produced action");});
scenario("S3-UNKNOWN-DOWN-STAYS-INERT-AFTER-OBSERVE",[](){S3DecisionBoundary s;feed(s,{edge(1,1)});s.observeNav(0,true);require(feed(s,{qual(1,QualifiedPhase::Short)}).count==0,"late nav applied to old down");feed(s,{edge(1,0)});feed(s,{edge(1,1)});require(contains(feed(s,{qual(1,QualifiedPhase::Short)}),S3ProposalKind::NavShort,1),"new valid press not working");});
scenario("S3-UNKNOWN-DOWN-CANNOT-BECOME-COMBO",[](){S3DecisionBoundary s;feed(s,{edge(1,1)});s.observeNav(0,true);feed(s,{qual(4,QualifiedPhase::ComboDown),edge(2,1)});require(s.physicalOwner(2)!=31&&feed(s,{qual(4,QualifiedPhase::Short)}).count==0,"ghost combo from unknown-down");});
scenario("S3-CONTEXT-MUST-BE-VALIDATED",[](){S3DecisionBoundary s;require(!s.observeNav(3,false),"accepted unverified nav");require(!s.navKnown(),"nav leak");require(!s.observeNav(-2,true),"invalid mode");require(s.observeNav(0,true)&&s.navKnown(),"verified nav");});
scenario("S3-NORMAL-BOT2-SHORT-PROPOSAL",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1)});auto p=feed(s,{qual(1,QualifiedPhase::Short)});require(contains(p,S3ProposalKind::NavShort,1)&&p.items[0].physical==1,"short");require(s.physicalOwner(1)==1,"owner stable");});
scenario("S3-NORMAL-BOT2-LONG-BEGIN-RELEASE",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1)});require(contains(feed(s,{qual(1,QualifiedPhase::LongBegin)}),S3ProposalKind::NavLong,1),"long begin");require(contains(feed(s,{qual(1,QualifiedPhase::LongRelease)}),S3ProposalKind::NavLongRelease,1),"long release");});
scenario("S3-SHIFT-CLOSED-INERT",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1)});auto p=feed(s,{qual(1,QualifiedPhase::ShiftClosed)});require(p.count==0&&s.physicalOwner(1)==1,"SHIFT action");});
scenario("S3-RAW-TRUE-UP-CLEARS-OWNER",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1)});feed(s,{edge(1,0)});require(!s.held(1)&&s.physicalOwner(1)==-1,"release missing");require(feed(s,{qual(1,QualifiedPhase::Short)}).count==0,"ghost after up");});
scenario("S3-ORPHAN-UP-DOES-NOTHING",[](){S3DecisionBoundary s;s.observeNav(0,true);auto p=feed(s,{edge(1,0)});require(!p.count&&s.ignored()==1,"orphan");});
scenario("S3-DUPLICATE-DOWN-IGNORED",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1)});feed(s,{edge(1,1)});require(s.physicalOwner(1)==1&&s.ignored()==1,"duplicate");});
scenario("S3-BROWSER-BOT2-CONTEXTUAL-UP",[](){S3DecisionBoundary s;s.observeNav(3,true);feed(s,{edge(1,1)});require(s.physicalOwner(1)==20,"browser owner");require(feed(s,{qual(1,QualifiedPhase::Short)}).count==0,"wrong regular shortcut");auto p=feed(s,{edge(1,0)});require(contains(p,S3ProposalKind::NavShort,1),"browser nav on true up");});
scenario("S3-BROWSER-BOT3-CONTEXTUAL-UP",[](){S3DecisionBoundary s;s.observeNav(7,true);feed(s,{edge(2,1)});require(s.physicalOwner(2)==20,"browser owner 2");auto p=feed(s,{edge(2,0)});require(contains(p,S3ProposalKind::NavShort,2),"browser nav true up");});
scenario("S3-MACHINE-BOT4-MODE-CYCLE",[](){S3DecisionBoundary s;s.observeNav(7,true);feed(s,{edge(3,1)});require(s.physicalOwner(3)==21,"special owner");auto p=feed(s,{edge(3,0)});require(contains(p,S3ProposalKind::ModeCycle,3),"mode cycle proposal");});
scenario("S3-NO-MODE-CYCLE-IF-NAV-CHANGED",[](){S3DecisionBoundary s;s.observeNav(7,true);feed(s,{edge(3,1)});s.observeNav(2,true);require(feed(s,{edge(3,0)}).count==0,"retargeted mode cycle");});
scenario("S3-BOT2-CAPTURE-PRESERVES-NAV",[](){S3DecisionBoundary s;s.observeNav(3,true);feed(s,{edge(1,1)});s.observeNav(0,true);auto p=feed(s,{edge(1,0)});require(p.count==1&&p.items[0].navAtDown==3&&p.items[0].navNow==0,"not captured");});
scenario("S3-STOP-HELD-REQUIRES-TRUE-UP",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1)});s.onHostStop();require(s.held(1)&&s.physicalOwner(1)==99,"stop ghost up");require(feed(s,{qual(1,QualifiedPhase::LongRelease)}).count==0,"STOP owe generated NAV");feed(s,{edge(1,0)});require(s.physicalOwner(1)==-1,"UP missing");});
scenario("S3-STOP-NO-REVIVED-OWNER",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(2,1)});s.onHostStop();s.observeNav(7,true);require(feed(s,{qual(2,QualifiedPhase::Short)}).count==0,"owner resurrected");});
scenario("S3-COMBO-1-2-CAPTURE-ORDER",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1)});feed(s,{qual(4,QualifiedPhase::ComboDown)});require(s.pendingCombo(),"combo not staged");feed(s,{edge(2,1)});require(!s.pendingCombo()&&s.physicalOwner(1)==30&&s.physicalOwner(2)==31,"combo not bound");auto p=feed(s,{qual(4,QualifiedPhase::Short)});require(contains(p,S3ProposalKind::Combo,4),"combo not accepted");});
scenario("S3-COMBO-1-2-WRONG-OWNER",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1),qual(4,QualifiedPhase::ComboDown)});feed(s,{edge(1,0)});feed(s,{edge(2,1)});require(feed(s,{qual(4,QualifiedPhase::Short)}).count==0,"missing first created ownership");});
scenario("S3-COMBO-CATALOG-SOURCE-SI",[](){const std::array<std::array<int,3>,6> pairs{{{{1,2,4}},{{2,1,5}},{{1,3,6}},{{2,3,7}},{{2,0,8}},{{1,0,9}}}};for(auto p:pairs){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(p[0],1),qual(p[2],QualifiedPhase::ComboDown),edge(p[1],1)});require(s.physicalOwner(p[0])==30&&s.physicalOwner(p[1])==31,"ownership catalog");require(contains(feed(s,{qual(p[2],QualifiedPhase::Short)}),S3ProposalKind::Combo,p[2]),"combo catalog");}});
scenario("S3-COMBO-DENY-MISMATCHED-ROLE",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1),qual(4,QualifiedPhase::ComboDown),edge(2,1)});require(feed(s,{qual(5,QualifiedPhase::Short)}).count==0,"other role steals release");});
scenario("S3-COMBO-DENY-RELEASE-AFTER-SECOND-UP",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1),qual(4,QualifiedPhase::ComboDown),edge(2,1),edge(2,0)});require(feed(s,{qual(4,QualifiedPhase::LongRelease)}).count==0,"ghost combo");});
scenario("S3-COMBO-STOP-CANCELS",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(1,1),qual(4,QualifiedPhase::ComboDown),edge(2,1)});s.onHostStop();require(feed(s,{qual(4,QualifiedPhase::LongRelease)}).count==0,"stale combo");});
scenario("S3-RED-DOES-NOT-EXECUTE-SNAPSHOT",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(0,1)});auto p=feed(s,{qual(0,QualifiedPhase::Short)});require(contains(p,S3ProposalKind::RedShort,0),"red not detected");});
scenario("S3-DJ2-ROT-DIAGNOSTIC-ONLY",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(2,1)});auto p=feed(s,{qual(10,QualifiedPhase::ComboDown),dj(21,65)});require(contains(p,S3ProposalKind::Dj2Rot,10)&&s.physicalOwner(2)==40,"DJ2 mark");require(!feed(s,{qual(10,QualifiedPhase::LongRelease)}).count,"DJ2 release shouldn't fire nav");});
scenario("S3-DJ2-REFUSED-AFTER-STOP",[](){S3DecisionBoundary s;s.observeNav(0,true);feed(s,{edge(2,1)});s.onHostStop();require(feed(s,{qual(10,QualifiedPhase::ComboDown)}).count==0,"stopped DJ2 was qualified");});
scenario("S3-CC-DJ-DO-NOT-MUTATE-NAV",[](){S3DecisionBoundary s;s.observeNav(3,true);auto p=feed(s,{cc(4,67),dj(20,32)});require(!p.count&&s.nav()==3,"raw altered nav");});
scenario("S3-INVALID-PHASE-IS-ATOMIC",[](){S3DecisionBoundary s;s.observeNav(0,true);GestureBatch b{};b.push(edge(1,1));b.push(qual(11,QualifiedPhase::Short));S3ProposalBatch out{};require(!s.accept(b,out)&&!s.held(1)&&out.count==0,"invalid batch mutated state");});
scenario("S3-INVALID-COMBO-ROLE-PHASE",[](){S3DecisionBoundary s;s.observeNav(0,true);GestureBatch b{};b.push(qual(1,QualifiedPhase::ComboDown));S3ProposalBatch p{};require(!s.accept(b,p)&&p.count==0,"z2 rule ignored");});
scenario("S3-INVALID-SHIFT-ROLE",[](){S3DecisionBoundary s;GestureBatch b{};b.push(qual(7,QualifiedPhase::ShiftClosed));S3ProposalBatch p{};require(!s.accept(b,p),"z2 shift rule");});
scenario("S3-PROPOSAL-OVERFLOW-IS-ATOMIC",[](){S3DecisionBoundary s;s.observeNav(0,true);GestureBatch b{};b.push(edge(1,1));S3ProposalBatch p{};p.count=20;require(!s.accept(b,p)&&!s.held(1),"capacity mutated");});
scenario("PIPELINE-S3-BOT2-SHORT-NO-MIDI",[](){CoreCoordinator c;require(c.observeS3NavForDiagnostic(0,true),"nav");push(c,0x90,13,127,0);push(c,0x80,13,0,40);require(c.s3TraceCount()==1&&c.s3Trace(0).kind==S3ProposalKind::NavShort,"pipeline nav");require(c.output().emitted()==0,"phantom note");});
scenario("PIPELINE-S3-COMBO-1-2-PHASE-ORDER",[](){CoreCoordinator c;require(c.observeS3NavForDiagnostic(0,true),"nav");push(c,0x90,13,127,0);push(c,0x90,14,127,20);require(c.s3().physicalOwner(1)==30&&c.s3().physicalOwner(2)==31,"pipeline combo source order");push(c,0x80,14,0,21);require(c.s3TraceCount()==1&&c.s3Trace(0).kind==S3ProposalKind::Combo,"pipeline combo up");});
scenario("PIPELINE-S3-STOP-DOESNT-ACTIVATE",[](){CoreCoordinator c;c.observeS3NavForDiagnostic(0,true);push(c,0x90,13,127,0);require(c.onHostStop(),"stop");push(c,0x80,13,0,250);require(c.s3TraceCount()==0&&c.output().emitted()==0,"stop restored ghost");});
scenario("PIPELINE-S3-UNKNOWN-NAV-STRICT",[](){CoreCoordinator c;push(c,0x90,13,127,0);push(c,0x80,13,0,30);require(c.s3TraceCount()==0&&c.output().emitted()==0,"unknown nav action");});
scenario("PIPELINE-S3-SHIFT-PRECEDES-CC",[](){CoreCoordinator c;c.observeS3NavForDiagnostic(0,true);push(c,0x90,13,127,0);push(c,0xB0,4,67,90);require(c.traceCount()==3&&c.trace(1).kind==GestureEventKind::Qualified&&c.trace(2).kind==GestureEventKind::RawCc,"order lost");require(c.s3TraceCount()==0,"SHIFT mutated music");});
scenario("PIPELINE-S3-WRONG-CHANNEL-ISOLATED",[](){CoreCoordinator c;c.observeS3NavForDiagnostic(0,true);require(!c.onMidi({15,0x90,13,127},0),"unexpected channel");require(!c.s3().held(1),"held changed");});
scenario("PIPELINE-S3-S4-EXPLICIT-ONLY",[](){CoreCoordinator c;c.observeS3NavForDiagnostic(0,true);c.enableTestMidiProjection(true);push(c,0x90,13,127,0);push(c,0x80,13,0,40);require(c.output().emitted()==0,"S3 proposal mapped to synth");require(c.applyLogicalOutput({10,4,100,127})&&c.output().emitted()==1,"explicit MIDI projection");});
std::cout<<"PASS "<<count<<" S3 boundary / integrated pipeline scenarios\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
